// patient_groups comes back as a JSON column — usually already parsed by the
// postgres node, but parse defensively in case it arrives as a string
const parseGroups = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string') { try { return JSON.parse(v) || []; } catch { return []; } }
  return [];
};

const producido = $('Query Balance Producido').all()
  .map(i => i.json)
  .filter(r => r && r.fecha)
  .map(r => ({
    fecha: r.fecha,
    doctor_id: r.doctor_id || null,
    doctor_name: r.doctor_name,
    patient_name: r.patient_name || '',
    service_name: r.service_name,
    invoice_doc_no: r.invoice_doc_no,
    currency: r.currency,
    importe: Number(r.importe || 0),
    patient_groups: parseGroups(r.patient_groups),
  }));

const cobrado = $('Query Balance Cobrado').all()
  .map(i => i.json)
  .filter(r => r && r.fecha)
  .map(r => ({
    fecha: r.fecha,
    doctor_id: r.doctor_id || null,
    doctor_name: r.doctor_name,
    patient_name: r.patient_name || '',
    invoice_doc_no: r.invoice_doc_no || '',
    payment_method: r.payment_method || 'N/D',
    currency: r.currency,
    importe: Number(r.importe || 0),
    patient_groups: parseGroups(r.patient_groups),
  }));

// Pendiente = Producido - Cobrado del mismo período, agrupado por médico + moneda,
// para que el saldo siempre cuadre con los totales mostrados en pantalla
const groups = new Map();
const ensure = (doctorId, doctorName, currency) => {
  const k = `${doctorId || 'null'}|${doctorName}|${currency}`;
  if (!groups.has(k)) {
    groups.set(k, { doctor_id: doctorId, doctor_name: doctorName, currency, total_facturado: 0, total_cobrado: 0 });
  }
  return groups.get(k);
};
for (const r of producido) {
  ensure(r.doctor_id, r.doctor_name, r.currency).total_facturado += r.importe;
}
for (const r of cobrado) {
  ensure(r.doctor_id, r.doctor_name, r.currency).total_cobrado += r.importe;
}
const pendiente = [...groups.values()]
  .map(g => ({ ...g, saldo: g.total_facturado - g.total_cobrado }))
  .sort((a, b) => a.doctor_name.localeCompare(b.doctor_name) || a.currency.localeCompare(b.currency));

// Pendiente por grupo de paciente — misma resta pero desglosada además por cada
// grupo (entre los filtrados) al que pertenece el paciente de cada línea. Un
// paciente en varios grupos aporta su línea a cada uno (se espera que sume más
// que el total general en ese caso, es intencional).
const groupBuckets = new Map();
const ensureGroupBucket = (groupId, groupName, doctorId, doctorName, currency) => {
  const k = `${groupId}|${doctorId || 'null'}|${currency}`;
  if (!groupBuckets.has(k)) {
    groupBuckets.set(k, { group_id: groupId, group_name: groupName, doctor_id: doctorId, doctor_name: doctorName, currency, total_facturado: 0, total_cobrado: 0 });
  }
  return groupBuckets.get(k);
};
for (const r of producido) {
  for (const g of r.patient_groups) {
    ensureGroupBucket(g.id, g.name, r.doctor_id, r.doctor_name, r.currency).total_facturado += r.importe;
  }
}
for (const r of cobrado) {
  for (const g of r.patient_groups) {
    ensureGroupBucket(g.id, g.name, r.doctor_id, r.doctor_name, r.currency).total_cobrado += r.importe;
  }
}
const pendiente_por_grupo = [...groupBuckets.values()]
  .map(g => ({ ...g, saldo: g.total_facturado - g.total_cobrado }))
  .sort((a, b) => a.group_name.localeCompare(b.group_name) || a.doctor_name.localeCompare(b.doctor_name) || a.currency.localeCompare(b.currency));

// ── Resumen: totales para la pestaña Resumen y la 1ra hoja de exportación ──
const _ensure = (map, k, seed) => { if (!map.has(k)) map.set(k, seed()); return map.get(k); };

const _prodDoc = new Map();
for (const r of producido) {
  _ensure(_prodDoc, `${r.doctor_id || 'null'}|${r.currency}`, () => ({ doctor_id: r.doctor_id, doctor_name: r.doctor_name, currency: r.currency, total: 0 })).total += r.importe;
}
const producido_por_doctor = [..._prodDoc.values()]
  .sort((a, b) => a.doctor_name.localeCompare(b.doctor_name) || a.currency.localeCompare(b.currency));

const _cobTot = new Map();
for (const r of cobrado) {
  _ensure(_cobTot, r.currency, () => ({ currency: r.currency, total: 0 })).total += r.importe;
}
const cobrado_total = [..._cobTot.values()].sort((a, b) => a.currency.localeCompare(b.currency));

// Atribución completa: una línea/pago cuya factura toca varios grupos suma a
// cada grupo; lo que no pertenece a ningún grupo cae en "Sin grupo".
const _byGroup = (rows) => {
  const m = new Map();
  for (const r of rows) {
    const gs = (r.patient_groups && r.patient_groups.length) ? r.patient_groups : [{ id: null, name: 'Sin grupo' }];
    for (const g of gs) {
      _ensure(m, `${g.id || 'null'}|${r.currency}`, () => ({ group_id: g.id || null, group_name: g.name, currency: r.currency, total: 0 })).total += r.importe;
    }
  }
  return [...m.values()].sort((a, b) => a.group_name.localeCompare(b.group_name) || a.currency.localeCompare(b.currency));
};
const cobrado_por_grupo = _byGroup(cobrado);
const producido_por_grupo = _byGroup(producido);
const resumen = { producido_por_doctor, cobrado_total, cobrado_por_grupo, producido_por_grupo };

// Totales por moneda — nunca se suman importes de monedas distintas
const _sumByCur = (rows) => {
  const m = new Map();
  for (const r of rows) m.set(r.currency, (m.get(r.currency) || 0) + r.importe);
  return m;
};
const _prodByCur = _sumByCur(producido);
const _cobByCur = _sumByCur(cobrado);
const by_currency = [...new Set([..._prodByCur.keys(), ..._cobByCur.keys()])]
  .sort()
  .map((currency) => {
    const total_producido = _prodByCur.get(currency) || 0;
    const total_cobrado = _cobByCur.get(currency) || 0;
    return { currency, total_producido, total_cobrado, total_pendiente: total_producido - total_cobrado };
  });
const num_doctores = new Set(pendiente.map(r => r.doctor_id).filter(Boolean)).size;

return [{ json: {
  summary: { by_currency, num_doctores },
  producido,
  cobrado,
  pendiente,
  pendiente_por_grupo,
  resumen
} }];
